begin;
set local search_path=public,private,extensions;
select plan(17);
select ok(not has_function_privilege('anon','public.get_my_provider_payment_proof_status(uuid,text)','EXECUTE'),'anonymous cannot inspect proof status');
select ok(has_function_privilege('authenticated','public.get_my_provider_payment_proof_status(uuid,text)','EXECUTE'),'authenticated actors use guarded status RPC');
select throws_ok($$select public.get_my_provider_payment_proof_status('11111111-1111-4111-8111-111111111111',repeat('a',64))$$,'42501',null,'proof status rejects unauthenticated actors');
select ok((select relrowsecurity from pg_class where oid='public.provider_billing_document_artifacts'::regclass),'billing artifact metadata enforces RLS');
select ok(not has_table_privilege('authenticated','public.provider_billing_document_artifacts','INSERT,UPDATE,DELETE'),'actors cannot rewrite archived billing PDFs');
select ok(not has_function_privilege('authenticated','public.register_provider_billing_document_artifact(uuid,text,uuid,text,text,text,text,jsonb,uuid)','EXECUTE'),'only trusted service archives PDFs');
select ok((select not public from storage.buckets where id='provider-billing'),'billing PDF bucket is private');
select ok((select count(*)=1 from pg_trigger where tgname='provider_billing_artifact_immutable'and not tgisinternal),'billing artifacts are immutable');
select throws_ok($$select public.register_provider_billing_document_artifact('11111111-1111-4111-8111-111111111111','invoice','22222222-2222-4222-8222-222222222222','fr',repeat('a',64),repeat('b',64),'forged.pdf','{}','33333333-3333-4333-8333-333333333333')$$,'42501',null,'archive command rejects absent trusted principal');
select ok((select relrowsecurity from pg_class where oid='public.provider_document_scan_jobs'::regclass),'qualification scan jobs enforce RLS');
select ok(not has_table_privilege('authenticated','public.provider_document_scan_jobs','INSERT,UPDATE,DELETE'),'providers cannot declare their own clean verdict');
select ok(not has_function_privilege('authenticated','public.record_provider_document_scan_result(uuid,text,text,text,text,text,uuid)','EXECUTE'),'providers cannot invoke trusted scanner');
select throws_ok($$select * from public.claim_provider_document_scan_jobs('11111111-1111-4111-8111-111111111111',1,300)$$,'42501','TRUSTED_SCANNER_SERVICE_REQUIRED','scanner claims require service role');
select ok((select count(*)=3 from pg_trigger where tgname in('provider_document_scan_results_immutable','provider_document_scan_retry_history_immutable','provider_document_scan_idempotency_immutable')and not tgisinternal),'scan evidence and retries are immutable');
select ok((select count(*)=1 from pg_trigger where tgname='provider_document_versions_clean_review'and not tgisinternal),'human verification is guarded by trusted clean scan');
select ok((select qual like '%CLEAN%' from pg_policies where policyname='provider_qualification_storage_scoped_read'),'direct Storage reads honor scan quarantine');
select ok((select count(*)=1 from pg_constraint where conname='provider_document_scan_state_check'),'scan state must bind a trusted result');
select * from finish();
rollback;
